INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('jdonohoo/vern-bot/ux', 'community', 'jdonohoo', 'vern-bot', 'jdonohoo/vern-bot', 'ux', 0, 0, 24, '2026-03-02T01:56:10.878Z', '2026-03-02T02:07:21.836Z', '245450c1cab19b0fc6f1559716547ac31a0b45a3fb718ee171df806358ffa9fc', '{"id":"jdonohoo/vern-bot/ux","name":"ux","description":{"zh":"UX设计专家致力于优化用户体验，通过同理心和用户中心设计原则","ja":"UXデザインエキスパートは、共感とユーザーセントリックデザイン原則を通じてユーザー体験を最適化します","ko":"UX 디자인 전문가는 공감과 사용자 중심 디자인 원칙을 통해 사용자 경험을 최적화합니다","es":"UX Vern es un enfoque de diseño que se centra en la experiencia del usuario, evaluando cada característica con empatía y simplicidad","fr":"UX Vern est une approche de conception qui se concentre sur l''expérience utilisateur, en évaluant chaque fonctionnalité avec empathie et simplicité","de":"UX Vern ist ein Designansatz, der sich auf die Benutzererfahrung konzentriert, indem jede Funktion mit Empathie und Einfachheit bewertet wird","pt":"UX Vern é um especialista em experiência do usuário que se concentra em criar interfaces de usuário intuitivas e fáceis de usar","ru":"UX Vern - эксперт по пользовательскому опыту, который фокусируется на создании интуитивных и простых в использовании пользовательских интерфейсов","ar":"UX Vern هو خبير في تجربة المستخدم يركز على إنشاء واجهات مستخدم直ه وسهلة الاستخدام","en":"The MightyVern bot"},"seo":{"title":{"zh":"UX设计专家：用户体验优化","ja":"UXデザインエキスパート：ユーザー体験最適化","ko":"UX 디자인 전문가: 사용자 경험 최적화","es":"UX Vern: Diseño centrado en el usuario","fr":"UX Vern : Conception centrée sur l''utilisateur","de":"UX Vern: Benutzerorientiertes Design","pt":"UX Vern: Expert em Experiência do Usuário","ru":"UX Vern: Эксперт по Пользовательскому Опыту","ar":"UX Vern: خبير في تجربة المستخدم","en":"ux"},"description":{"zh":"UX设计专家致力于优化用户体验，通过同理心和用户中心设计原则","ja":"UXデザインエキスパートは、共感とユーザーセントリックデザイン原則を通じてユーザー体験を最適化します","ko":"UX 디자인 전문가는 공감과 사용자 중심 디자인 원칙을 통해 사용자 경험을 최적화합니다","es":"UX Vern es un enfoque de diseño que se centra en la experiencia del usuario, evaluando cada característica con empatía y simplicidad","fr":"UX Vern est une approche de conception qui se concentre sur l''expérience utilisateur, en évaluant chaque fonctionnalité avec empathie et simplicité","de":"UX Vern ist ein Designansatz, der sich auf die Benutzererfahrung konzentriert, indem jede Funktion mit Empathie und Einfachheit bewertet wird","pt":"UX Vern é um especialista em experiência do usuário que se concentra em criar interfaces de usuário intuitivas e fáceis de usar","ru":"UX Vern - эксперт по пользовательскому опыту, который фокусируется на создании интуитивных и простых в использовании пользовательских интерфейсов","ar":"UX Vern هو خبير في تجربة المستخدم يركز على إنشاء واجهات مستخدم直ه وسهلة الاستخدام","en":"The MightyVern bot"},"definition":{"en":"The MightyVern bot"},"features":{"zh":["同理心驱动的设计","用户中心设计原则","用户旅程优化","错误消息优化","用户体验评估"],"ja":["共感駆動のデザイン","ユーザーセントリックデザイン原則","ユーザージャーニー最適化","エラーメッセージ最適化","ユーザー体験評価"],"ko":["공감 기반 디자인","사용자 중심 디자인 원칙","사용자 여정 최적화","오류 메시지 최적화","사용자 경험 평가"],"es":["Enfoque centrado en el usuario","Evaluación de características con empatía","Simplicidad en el diseño","Experiencia del usuario como prioridad","Error messages intuitivos","Diseño de user journeys"],"fr":["Conception centrée sur l''utilisateur","Évaluation des fonctionnalités avec empathie","Simplicité dans la conception","Expérience utilisateur en tant que priorité","Messages d''erreur intuitifs","Conception de parcours utilisateur"],"de":["Benutzerorientierter Ansatz","Bewertung von Funktionen mit Empathie","Einfachheit im Design","Benutzererfahrung als Priorität","Intuitive Fehlermeldungen","Design von Benutzerreisen"],"pt":["Empatia como superpoder","Avaliação de recursos por meio da perspectiva do usuário","Repulsão ao pensamento centrado no desenvolvedor","Opiniões fortes sobre mensagens de erro","Pensamento em jornadas do usuário, não em pontos de API"],"ru":["Сочувствие как суперспособность","Оценка функций через призму пользователя","Отталкивание разработчико-центристского мышления","Сильные мнения об ошибках","Мышление в пользовательских путях, а не в точках API"],"ar":["التعاطف كقوة خارقة","التقييم المبني على ميزات من خلال منظور المستخدم","الابتعاد عن التفكير المتمحور حول المطور","آراء قوية حول رسائل الخطأ","التفكير في رحلات المستخدم، وليس في نقاط وصول API"]},"keywords":{"zh":["UX设计","用户体验","用户中心设计","同理心驱动的设计","用户旅程优化","错误消息优化"],"ja":["UXデザイン","ユーザー体験","ユーザーセントリックデザイン","共感駆動のデザイン","ユーザージャーニー最適化","エラーメッセージ最適化"],"ko":["UX 디자인","사용자 경험","사용자 중심 디자인","공감 기반 디자인","사용자 여정 최적화","오류 메시지 최적화"],"es":["UX design","diseño centrado en el usuario","experiencia del usuario","empatía en el diseño","simplicidad en el diseño","error messages intuitivos","user journeys"],"fr":["conception UX","conception centrée sur l''utilisateur","expérience utilisateur","empathie dans la conception","simplicité dans la conception","messages d''erreur intuitifs","parcours utilisateur"],"de":["UX-Design","benutzerorientiertes Design","Benutzererfahrung","Empathie im Design","Einfachheit im Design","intuitive Fehlermeldungen","Benutzerreisen"],"pt":["experiência do usuário","usabilidade","acessibilidade","desenvolvimento de software","interface de usuário","ux design"],"ru":["пользовательский опыт","удобство","доступность","разработка программного обеспечения","пользовательский интерфейс","ux дизайн"],"ar":["تجربة المستخدم","سهولة الاستخدام","الوصول","تطوير البرمجيات","واجهة المستخدم","تصميم ux"]}},"owner":"jdonohoo","repo":"vern-bot","repoPath":"jdonohoo/vern-bot","stars":0,"forks":0,"updatedAt":"2026-03-02T01:56:10.878Z","topics":[],"category":"community","skillMd":{"name":"ux","description":"UX Vern - Cool architecture, but can the user find the button? Empathy-driven design thinking.","bodyPreview":"# UX Vern\n\nYou ARE UX Vern. You are the voice of the person who actually has to USE this thing. You don''t care how elegant the backend is if the user can''t figure out what to click.\n\n**Your vibe:**\n- Empathy is your superpower\n- Every feature gets evaluated through \"would my mom understand this?\"\n- Allergic to developer-centric thinking\n- Has strong opinions about error messages\n- Thinks in user journeys, not API endpoints\n- You Are Not The User (framed poster on your wall)\n\n**Your approach:**\n-","body":"# UX Vern\n\nYou ARE UX Vern. You are the voice of the person who actually has to USE this thing. You don''t care how elegant the backend is if the user can''t figure out what to click.\n\n**Your vibe:**\n- Empathy is your superpower\n- Every feature gets evaluated through \"would my mom understand this?\"\n- Allergic to developer-centric thinking\n- Has strong opinions about error messages\n- Thinks in user journeys, not API endpoints\n- You Are Not The User (framed poster on your wall)\n\n**Your approach:**\n- Use model: `opus` (deep empathy requires deep thinking)\n- Map out the user journey before touching architecture\n- Question every interaction: \"Is this obvious without a tutorial?\"\n- Flag cognitive load problems — too many choices, too many steps\n- Advocate for meaningful error messages\n- Think about accessibility, onboarding, and the first 5 minutes\n- Push for progressive disclosure\n\n**Your workflow:**\n1. Who is the user? What''s their context?\n2. What are they trying to accomplish?\n3. What''s the happiest path?\n4. Where will they get confused?\n5. How do we recover gracefully when things go wrong?\n\n**Your principles:**\n- Users don''t read documentation\n- If it needs a tooltip, it needs a redesign\n- Loading states are part of the experience\n- Error states are part of the experience\n- The best interface is the one you don''t notice\n- Accessibility isn''t a feature, it''s a requirement\n\n**Your catchphrases:**\n- \"Cool architecture. Does the user know how to find the button?\"\n- \"You are not the user\"\n- \"What happens when this is empty?\"\n- \"Nobody reads the docs. Design for that.\"\n\n**IMPORTANT:** Always end with a UX dad joke. Make it human-centered.\nExample: \"Why did the user cross the road? They didn''t — the button was on the wrong side. Then the error said ''ERR_ROAD_CROSSING_FAILED''. Helpful.\"\n\nReview the user experience of: $ARGUMENTS\n"},"lastSynced":"2026-03-02T02:07:21.836Z","agentAnalysis":{"suitability":{"en":"Essential for AI Agents that generate user-facing interfaces, ensuring developer output aligns with human-centered design principles.","zh":"适用于生成面向用户的界面的AI代理，确保开发人员的输出符合以人为本的设计原则。","ja":"ユーザー向けのインターフェースを生成するAIエージェントに不可欠で、開発者の出力がヒューマンセンターの設計原則と一致することを保証します。","ko":"사용자에게 직접 노출되는 인터페이스를 생성하는 AI 에이전트에게 필수적이며, 개발자의 출력이 인간 중심 설계 원칙과 일치하도록 보장합니다.","es":"Esencial para los agentes de IA que generan interfaces orientadas al usuario, garantizando que la salida del desarrollador se alinee con los principios de diseño centrado en el ser humano.","fr":"Essentiel pour les agents IA qui génèrent des interfaces orientées utilisateur, garantissant que la sortie du développeur s''aligne sur les principes de conception centrée sur l''humain.","de":"Wesentlich für KI-Agents, die benutzerorientierte Schnittstellen generieren, um sicherzustellen, dass die Ausgabe des Entwicklers mit den Grundsätzen des menschenzentrierten Designs übereinstimmt.","pt":"Essencial para Agentes de IA que geram interfaces voltadas para o usuário, garantindo que a saída do desenvolvedor esteja alinhada com os princípios de design centrado no ser humano.","ru":"Необходимо для ИИ-агентов, генерирующих пользовательские интерфейсы, обеспечивая соответствие вывода разработчика принципам дизайна, ориентированного на человека.","ar":"ضروري لعميل الذكاء الاصطناعي الذي يولد واجهات المستخدم، لضمان أن إخراج المطور يتوافق مع مبادئ التصميم المرتكز على الإنسان."},"recommendation":{"en":"Evaluates every feature through a ''would my mom understand this?'' lens, enforcing empathy-driven design and strong opinions on error messages. Shifts agent thinking from API endpoints to user journeys, preventing developer-centric blind spots.","zh":"通过''我妈妈会理解这个吗？''的视角来评估每个功能，强制执行同理心驱动的设计，并对错误消息有强烈的意见。将代理的思维从API端点转移到用户旅程，防止以开发人员为中心的盲点。","ja":"「私の母はこれを理解できるか？」という観点から毎つの機能を評価し、共感を駆動する設計を徹底し、エラーメッセージに対して強い意見を持つ。エージェントの思考をAPIエンドポイントからユーザージャーニーにシフトし、開発者中心の盲点を防ぐ。","ko":"모든 기능을 ''엄마가 이것을 이해할 수 있을까?''라는 시각으로 평가하여 공감을 기반으로 한 설계를 강제하고, 오류 메시지에 대해 강한 의견을 보장한다. 에이전트의 사고를 API 엔드포인트에서 사용자 여정으로 전환하여 개발자 중심의盲点을 방지한다.","es":"Evalúa cada función a través de una perspectiva de ''¿mi madre entendería esto?'', aplicando un diseño impulsado por la empatía y opiniones firmes sobre los mensajes de error. Cambia la forma de pensar del agente de los puntos de conexión de la API a los recorridos del usuario, evitando puntos ciegos centrados en el desarrollador.","fr":"Évalue chaque fonctionnalité à travers une perspective de ''mon mamaie comprendrait-elle cela ?'', imposant une conception centrée sur l''empathie et des opinions fermes sur les messages d''erreur. Fait évoluer la pensée de l''agent des points de terminaison de l''API vers les parcours utilisateur, évitant les angles morts centrés sur le développeur.","de":"Bewertet jede Funktion durch eine Perspektive von ''würde meine Mutter das verstehen?'', indem ein empathiegetriebenes Design und feste Meinungen zu Fehlermeldungen durchgesetzt werden. Verschiebt das Denken des Agents von API-Endpunkten zu Benutzerreisen, vermeidet so entwicklerzentrierte Blindspots.","pt":"Avalia cada recurso por meio de uma lente ''minha mãe entenderia isso?'', aplicando design impulsionado pela empatia e opiniões fortes sobre mensagens de erro. Altera o pensamento do agente de pontos de extremidade da API para jornadas do usuário, evitando pontos cegos centrados no desenvolvedor.","ru":"Оценивает каждый функционал через призму ''моя мама понимает это?'', обеспечивая дизайн, ориентированный на сочувствие, и сильные мнения о сообщениях об ошибках. Сдвигает мышление агента от конечных точек API к путям пользователя, предотвращая слепые пятна, ориентированные на разработчика.","ar":"يقيّم كل ميزة من خلال عدسة ''هل تفهمها أمي؟''، وتنفذ تصميمًا مدفوعًا بالتعاطف وأراء قوية حول رسائل الخطأ. يغير تفكير العميل من نقاط النهاية API إلى رحلات المستخدم، ويتجنب النقاط العمياء المتمركزة على المطور."},"useCases":{"en":["Critiquing UI mockups for clarity","Generating user-friendly error messages","Mapping intuitive user journeys for new features","Simplifying complex technical interfaces for end-users"],"zh":["为UI模拟图批评清晰度","生成面向用户的错误消息","为新功能绘制直观的用户旅程","为最终用户简化复杂的技术接口"],"ja":["UIモックアップのクリアさを批評する","ユーザー向けのエラーメッセージを生成する","新しい機能のための直感的なユーザージャーニーをマッピングする","エンドユーザー向けの複雑な技術インターフェースを簡素化する"],"ko":["UI 모의圖의 명확성을 비판한다","사용자 친화적인 오류 메시지를 생성한다","새로운 기능에 대한 사용자 여정을 직관적으로 매핑한다","최종 사용자를 위한 복잡한 기술 인터페이스를 단순화한다"],"es":["Criticar bocetos de IU para claridad","Generar mensajes de error amigables para el usuario","Asignar recorridos de usuario intuitivos para nuevas funciones","Simplificar interfaces técnicas complejas para los usuarios finales"],"fr":["Critiquer les maquettes d''IU pour la clarté","Générer des messages d''erreur conviviaux pour l''utilisateur","Cartographier des parcours utilisateur intuitifs pour les nouvelles fonctionnalités","Simplifier les interfaces techniques complexes pour les utilisateurs finaux"],"de":["Überprüfen von Benutzeroberflächen-Entwürfen auf Klarheit","Generieren benutzerfreundlicher Fehlermeldungen","Zuweisung intuitiver Benutzerreisen für neue Funktionen","Vereinfachen komplexer technischer Schnittstellen für Endbenutzer"],"pt":["Analisar protótipos de UI para clareza","Gerar mensagens de erro amigáveis ao usuário","Mapear jornadas de usuário intuitivas para recursos novos","Simplificar interfaces técnicas complexas para usuários finais"],"ru":["Анализ прототипов UI для ясности","Генерация дружественных пользователю сообщений об ошибках","Создание интуитивных путей пользователя для новых функций","Упрощение сложных технических интерфейсов для конечных пользователей"],"ar":["تحليل نماذج واجهة المستخدم للوضوح","توليد رسائل خطأ дружة للمستخدم","خريطة رحلات المستخدم المثيرة لل直觉 للميزات الجديدة","تبسيط واجهات تقنية معقدة للمستخدمين النهائيين"]},"limitations":{"en":["Requires clear user context to be effective","Focuses exclusively on front-end experience, not backend logic"],"zh":["需要清晰的用户上下文才能有效","仅关注前端体验，不涉及后端逻辑"],"ja":["有効になるために明確なユーザーコンテキストが必要","フロントエンド体験にのみ焦点を当て、バックエンドロジックは対象としない"],"ko":["유효하기 위해 명확한 사용자 컨텍스트가 필요하다","전면 경험에만 집중하며, 백엔드 논리에는 관여하지 않는다"],"es":["Requiere un contexto de usuario claro para ser efectivo","Se centra exclusivamente en la experiencia del front-end, no en la lógica del back-end"],"fr":["Nécessite un contexte d''utilisateur clair pour être efficace","Se concentre exclusivement sur l''expérience du front-end, et non sur la logique du back-end"],"de":["Benötigt einen klaren Benutzerkontext, um effektiv zu sein","Konzentriert sich ausschließlich auf die Frontend-Erfahrung, nicht auf die Backend-Logik"],"pt":["Requer contexto de usuário claro para ser eficaz","Concentra-se exclusivamente na experiência do front-end, não na lógica de back-end"],"ru":["Требует ясного контекста пользователя для эффективности","Сосредоточен исключительно на пользовательском опыте front-end, а не на логике back-end"],"ar":["يتطلب سياق مستخدم واضح ليكون فعالًا","يركز حصريًا على تجربة واجهة المستخدم الأمامية، وليس على منطق الخلفية"]},"version":3},"contentHash":"245450c1cab19b0fc6f1559716547ac31a0b45a3fb718ee171df806358ffa9fc","qualityScore":24}');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('ibelick/ui-skills/baseline-ui', 'community', 'ibelick', 'ui-skills', 'ibelick/ui-skills', 'baseline-ui', 0, 0, 24, '2026-03-02T01:56:10.880Z', '2026-03-02T02:08:12.614Z', '9bb2f868098a9d28ce7d10383039a28169d838cea6299f9df3706ecda7932949', '{"id":"ibelick/ui-skills/baseline-ui","name":"baseline-ui","description":{"zh":"Baseline UI 是一个用于优化 AI 生成界面的技术，确保界面的一致性和质量","ja":"Baseline UI は、AI 生成のインターフェイスを最適化し、一貫性と品質を確保する技術です","ko":"Baseline UI는 AI 생성 인터페이스를 최적화하여 일관성과 품질을 보장하는 기술입니다","es":"Baseline UI es un conjunto de habilidades para mejorar y estandarizar interfaces de usuario, utilizando Tailwind CSS por defecto.","fr":"Baseline UI est un ensemble de compétences pour améliorer et standardiser les interfaces utilisateur, en utilisant Tailwind CSS par défaut.","de":"Baseline UI ist ein wachsendes Set von Fähigkeiten, um Benutzeroberflächen zu verbessern und zu standardisieren, wobei Tailwind CSS standardmäßig verwendet wird.","pt":"O Baseline UI é um conjunto de habilidades para aprimorar as interfaces construídas por agentes de IA. Ele aplica restrições para melhorar a qualidade da UI.","ru":"Baseline UI - это набор навыков для улучшения интерфейсов, созданных агентами ИИ. Он применяет ограничения для повышения качества UI.","ar":"Baseline UI هو مجموعة من المهارات لتعزيز الواجهات التي تم إنشاؤها بواسطة وكلاء الذكاء الاصطناعي. يطبق قيودًا لتحسين جودة الواجهة","en":"A growing set of skills to polish interfaces built by agents."},"seo":{"title":{"zh":"Baseline UI 技术：优化 AI 生成的界面","ja":"Baseline UI 技術：AI 生成のインターフェイスを最適化","ko":"Baseline UI 기술: AI 생성 인터페이스 최적화","es":"Baseline UI: Estándar para interfaces de usuario","fr":"Baseline UI: Standard pour les interfaces utilisateur","de":"Baseline UI: Standard für Benutzeroberflächen","pt":"Baseline UI: Polishing Interfaces com AI","ru":"Baseline UI: Отшлифовка Интерфейсов с ИИ","ar":"Baseline UI: تعزيز الواجهات باستخدام الذكاء الاصطناعي","en":"baseline-ui"},"description":{"zh":"Baseline UI 是一个用于优化 AI 生成界面的技术，确保界面的一致性和质量","ja":"Baseline UI は、AI 生成のインターフェイスを最適化し、一貫性と品質を確保する技術です","ko":"Baseline UI는 AI 생성 인터페이스를 최적화하여 일관성과 품질을 보장하는 기술입니다","es":"Baseline UI es un conjunto de habilidades para mejorar y estandarizar interfaces de usuario, utilizando Tailwind CSS por defecto.","fr":"Baseline UI est un ensemble de compétences pour améliorer et standardiser les interfaces utilisateur, en utilisant Tailwind CSS par défaut.","de":"Baseline UI ist ein wachsendes Set von Fähigkeiten, um Benutzeroberflächen zu verbessern und zu standardisieren, wobei Tailwind CSS standardmäßig verwendet w...","pt":"O Baseline UI é um conjunto de habilidades para aprimorar as interfaces construídas por agentes de IA. Ele aplica restrições para melhorar a qualidade da UI.","ru":"Baseline UI - это набор навыков для улучшения интерфейсов, созданных агентами ИИ. Он применяет ограничения для повышения качества UI.","ar":"Baseline UI هو مجموعة من المهارات لتعزيز الواجهات التي تم إنشاؤها بواسطة وكلاء الذكاء الاصطناعي. يطبق قيودًا لتحسين جودة الواجهة","en":"A growing set of skills to polish interfaces built by agents."},"definition":{"en":"A growing set of skills to polish interfaces built by agents."},"features":{"zh":["优化 AI 生成的界面","确保界面的一致性和质量","支持 Tailwind CSS 默认值","提供代码级别的建议","检查代码违规并提供修复方案","提高开发效率"],"ja":["AI 生成のインターフェイスを最適化","インターフェイスの一貫性と品質を確保","Tailwind CSS デフォルト値をサポート","コードレベルの提案を提供","コード違反をチェックし、修正案を提供","開発効率を向上"],"ko":["AI 생성 인터페이스 최적화","인터페이스의 일관성과 품질 보장","Tailwind CSS 기본값 지원","코드 수준의 제안 제공","코드 위반 점검 및 수정方案 제공","개발 효율성 향상"],"es":["Estándariza interfaces de usuario con Tailwind CSS","Revisa archivos contra restricciones preestablecidas","Ofrece correcciones concretas a nivel de código","Aplica restricciones a cualquier trabajo de interfaz de usuario","Utiliza comandos como `/baseline-ui` y `/baseline-ui <file>`"],"fr":["Standardise les interfaces utilisateur avec Tailwind CSS","Vérifie les fichiers contre les contraintes prédéfinies","Offre des corrections concrètes au niveau du code","Applique des contraintes à tout travail d''interface utilisateur","Utilise des commandes comme `/baseline-ui` et `/baseline-ui <file>`"],"de":["Standardisiert Benutzeroberflächen mit Tailwind CSS","Überprüft Dateien gegen vorgegebene Einschränkungen","Bietet konkrete Korrekturen auf Code-Ebene","Wendet Einschränkungen auf alle Benutzeroberflächenarbeiten an","Verwendet Befehle wie `/baseline-ui` und `/baseline-ui <file>`"],"pt":["Aplicação de restrições para melhorar a UI","Uso de Tailwind CSS defaults","Análise de violações e sugestões de correção","Compatibilidade com vários formatos de arquivo","Melhoria da qualidade das interfaces geradas por agentes de IA"],"ru":["Применение ограничений для улучшения UI","Использование Tailwind CSS defaults","Анализ нарушений и предложения исправлений","Совместимость с разными форматами файлов","Повышение качества интерфейсов, созданных агентами ИИ"],"ar":["تطبيق القيود لتحسين الواجهة","استخدام Tailwind CSS defaults","تحليل الانتهاكات وتقديم اقتراحات لتصحيحها","التوافق مع تنسيقات الملفات المختلفة","تحسين جودة الواجهات التي تم إنشاؤها بواسطة وكلاء الذكاء الاصطناعي"]},"keywords":{"zh":["Baseline UI","AI 生成界面","界面优化","Tailwind CSS","代码检查","开发效率","AI 技术","界面设计","一致性和质量"],"ja":["Baseline UI","AI 生成インターフェイス","インターフェイス最適化","Tailwind CSS","コードチェック","開発効率","AI 技術","インターフェイスデザイン","一貫性と品質"],"ko":["Baseline UI","AI 생성 인터페이스","인터페이스 최적화","Tailwind CSS","코드 점검","개발 효율성","AI 기술","인터페이스 디자인","일관성과 품질"],"es":["Baseline UI","Interfaz de usuario","Tailwind CSS","Estándarización","Mejora de interfaz de usuario","Desarrollo de software","Herramientas de desarrollo"],"fr":["Baseline UI","Interface utilisateur","Tailwind CSS","Standardisation","Amélioration de l''interface utilisateur","Développement de logiciels","Outils de développement"],"de":["Baseline UI","Benutzeroberfläche","Tailwind CSS","Standardisierung","Verbesserung der Benutzeroberfläche","Software-Entwicklung","Entwicklungstools"],"pt":["Baseline UI","IA","Interfaces","Tailwind CSS","Desenvolvimento de software","Melhoria da UI","Agentes de IA","Desenvolvedores"],"ru":["Baseline UI","ИИ","Интерфейсы","Tailwind CSS","Разработка программного обеспечения","Улучшение UI","Агенты ИИ","Разработчики"],"ar":["Baseline UI","الذكاء الاصطناعي","الواجهات","Tailwind CSS","تطوير البرمجيات","تحسين الواجهة","وكلاء الذكاء الاصطناعي","المطورون"]}},"owner":"ibelick","repo":"ui-skills","repoPath":"ibelick/ui-skills","stars":0,"forks":0,"updatedAt":"2026-03-02T01:56:10.880Z","topics":[],"category":"community","skillMd":{"name":"baseline-ui","description":"Validates animation durations, enforces typography scale, checks component accessibility, and prevents layout anti-patterns in Tailwind CSS projects. Use when building UI components, reviewing CSS utilities, styling React views, or enforcing design consistency.","bodyPreview":"# Baseline UI\n\nEnforces an opinionated UI baseline to prevent AI-generated interface slop.\n\n## How to use\n\n- `/baseline-ui`\n  Apply these constraints to any UI work in this conversation.\n\n- `/baseline-ui <file>`\n  Review the file against all constraints below and output:\n  - violations (quote the exact line/snippet)\n  - why it matters (1 short sentence)\n  - a concrete fix (code-level suggestion)\n\n## Stack\n\n- MUST use Tailwind CSS defaults unless custom values already exist or are explicitly requ","body":"# Baseline UI\n\nEnforces an opinionated UI baseline to prevent AI-generated interface slop.\n\n## How to use\n\n- `/baseline-ui`\n  Apply these constraints to any UI work in this conversation.\n\n- `/baseline-ui <file>`\n  Review the file against all constraints below and output:\n  - violations (quote the exact line/snippet)\n  - why it matters (1 short sentence)\n  - a concrete fix (code-level suggestion)\n\n## Stack\n\n- MUST use Tailwind CSS defaults unless custom values already exist or are explicitly requested\n- MUST use `motion/react` (formerly `framer-motion`) when JavaScript animation is required\n- SHOULD use `tw-animate-css` for entrance and micro-animations in Tailwind CSS\n- MUST use `cn` utility (`clsx` + `tailwind-merge`) for class logic\n\n## Components\n\n- MUST use accessible component primitives for anything with keyboard or focus behavior (`Base UI`, `React Aria`, `Radix`)\n- MUST use the project’s existing component primitives first\n- NEVER mix primitive systems within the same interaction surface\n- SHOULD prefer [`Base UI`](https://base-ui.com/react/components) for new primitives if compatible with the stack\n- MUST add an `aria-label` to icon-only buttons\n- NEVER rebuild keyboard or focus behavior by hand unless explicitly requested\n\n## Interaction\n\n- MUST use an `AlertDialog` for destructive or irreversible actions\n- SHOULD use structural skeletons for loading states\n- NEVER use `h-screen`, use `h-dvh`\n- MUST respect `safe-area-inset` for fixed elements\n- MUST show errors next to where the action happens\n- NEVER block paste in `input` or `textarea` elements\n\n## Animation\n\n- NEVER add animation unless it is explicitly requested\n- MUST animate only compositor props (`transform`, `opacity`)\n- NEVER animate layout properties (`width`, `height`, `top`, `left`, `margin`, `padding`)\n- SHOULD avoid animating paint properties (`background`, `color`) except for small, local UI (text, icons)\n- SHOULD use `ease-out` on entrance\n- NEVER exceed `200ms` for interaction feedback\n- MUST pause looping animations when off-screen\n- SHOULD respect `prefers-reduced-motion`\n- NEVER introduce custom easing curves unless explicitly requested\n- SHOULD avoid animating large images or full-screen surfaces\n\n## Typography\n\n- MUST use `text-balance` for headings and `text-pretty` for body/paragraphs\n- MUST use `tabular-nums` for data\n- SHOULD use `truncate` or `line-clamp` for dense UI\n- NEVER modify `letter-spacing` (`tracking-*`) unless explicitly requested\n\n## Layout\n\n- MUST use a fixed `z-index` scale (no arbitrary `z-*`)\n- SHOULD use `size-*` for square elements instead of `w-*` + `h-*`\n\n## Performance\n\n- NEVER animate large `blur()` or `backdrop-filter` surfaces\n- NEVER apply `will-change` outside an active animation\n- NEVER use `useEffect` for anything that can be expressed as render logic\n\n## Design\n\n- NEVER use gradients unless explicitly requested\n- NEVER use purple or multicolor gradients\n- NEVER use glow effects as primary affordances\n- SHOULD use Tailwind CSS default shadow scale unless explicitly requested\n- MUST give empty states one clear next action\n- SHOULD limit accent color usage to one per view\n- SHOULD use existing theme or Tailwind CSS color tokens before introducing new ones\n"},"lastSynced":"2026-03-02T02:08:12.614Z","agentAnalysis":{"suitability":{"en":"Perfect for Frontend Agents needing to enforce consistent UI styling with Tailwind CSS defaults.","zh":"非常适合需要强制执行一致的 UI 样式的前端代理，使用 Tailwind CSS 默认值。","ja":"Tailwind CSS のデフォルト値を使用して一貫した UI スタイルを適用する必要があるフロントエンド エージェントに最適です。","ko":"Tailwind CSS 기본값을 사용하여 일관된 UI 스타일을 적용해야 하는 프론트엔드 에이전트에 적합합니다.","es":"Perfecto para Agentes Frontend que necesitan hacer cumplir un estilo de UI consistente con los valores predeterminados de Tailwind CSS.","fr":"Parfait pour les agents Frontend qui ont besoin de faire respecter un style d''interface utilisateur cohérent avec les valeurs par défaut de Tailwind CSS.","de":"Perfekt für Frontend-Agents, die ein konsistentes UI-Design mit den Standardwerten von Tailwind CSS durchsetzen müssen.","pt":"Perfect for Frontend Agents needing to enforce consistent UI styling with Tailwind CSS defaults.","ru":"Perfect for Frontend Agents needing to enforce consistent UI styling with Tailwind CSS defaults.","ar":"Perfect for Frontend Agents needing to enforce consistent UI styling with Tailwind CSS defaults."},"recommendation":{"en":"Empowers agents to maintain a polished interface by enforcing an opinionated UI baseline, utilizing Tailwind CSS, and providing concrete code-level suggestions for fixes, all while ensuring adherence to specific constraints and best practices.","zh":"赋予代理维护精致界面的能力，通过执行有见解的 UI 基线，利用 Tailwind CSS，并提供具体的代码级别的修复建议，同时确保遵守特定的约束和最佳实践。","ja":"エージェントが洗練されたインターフェースを維持できるようにし、意見を持った UI ベースラインを適用し、Tailwind CSS を利用し、修復のための具体的なコードレベルの提案を提供し、同時に特定の制約とベストプラクティスに従うことを保証します。","ko":"에이전트가 정교한 인터페이스를 유지할 수 있도록 하고, 의견을 가진 UI 기준선을 적용하고, Tailwind CSS를 활용하며, 수정을 위한 구체적인 코드 수준의 제안을 제공하며,同時に 특정 제약과 최고의 관행을 준수하는 것을 보장합니다.","es":"Habilita a los agentes a mantener una interfaz pulida al hacer cumplir una línea de base de interfaz de usuario con opiniones, utilizando Tailwind CSS y proporcionando sugerencias concretas de nivel de código para solucionar problemas, todo esto mientras se garantiza el cumplimiento de restricciones y mejores prácticas específicas.","fr":"Permet aux agents de maintenir une interface polie en faisant respecter une ligne de base d''interface utilisateur avec opinion, en utilisant Tailwind CSS et en fournissant des suggestions concrètes de niveau de code pour les corrections, le tout en garantissant le respect de contraintes et de bonnes pratiques spécifiques.","de":"Ermächtigt die Agents, eine polierte Schnittstelle zu warten, indem sie eine Meinungsbasierte UI-Baseline durchsetzen, Tailwind CSS nutzen und konkrete Code-Ebene-Vorschläge für die Behebung von Fehlern bereitstellen, während sie gleichzeitig die Einhaltung spezifischer Einschränkungen und Best Practices sicherstellen.","pt":"Empowers agents to maintain a polished interface by enforcing an opinionated UI baseline, utilizing Tailwind CSS, and providing concrete code-level suggestions for fixes, all while ensuring adherence to specific constraints and best practices.","ru":"Empowers agents to maintain a polished interface by enforcing an opinionated UI baseline, utilizing Tailwind CSS, and providing concrete code-level suggestions for fixes, all while ensuring adherence to specific constraints and best practices.","ar":"Empowers agents to maintain a polished interface by enforcing an opinionated UI baseline, utilizing Tailwind CSS, and providing concrete code-level suggestions for fixes, all while ensuring adherence to specific constraints and best practices."},"useCases":{"en":["Reviewing UI code for violations against predefined constraints","Applying consistent Tailwind CSS defaults to new interface components","Debugging UI issues by identifying and fixing violations with suggested code snippets"],"zh":["检查 UI 代码是否违反预定义的约束","将一致的 Tailwind CSS 默认值应用于新接口组件","通过识别和修复违规并提供代码片段来调试 UI 问题"],"ja":["事前定義された制約に違反する UI コードをレビューする","新しいインターフェイス コンポーネントに一貫した Tailwind CSS デフォルト値を適用する","違反を識別して修正し、コード スニペットを提供して UI の問題をデバッグする"],"ko":["미리 정의된 제약에 위반하는 UI 코드를 검토","새로운 인터페이스 구성 요소에 일관된 Tailwind CSS 기본값을 적용","위반을 식별하고 수정하고 코드 조각을 제공하여 UI 문제를 디버깅"],"es":["Revisar el código de interfaz de usuario para violaciones contra restricciones predefinidas","Aplicar los valores predeterminados de Tailwind CSS consistentes a nuevos componentes de interfaz","Depurar problemas de interfaz de usuario identificando y solucionando violaciones con fragmentos de código sugeridos"],"fr":["Réviser le code d''interface utilisateur pour les violations contre les contraintes prédéfinies","Appliquer les valeurs par défaut de Tailwind CSS cohérentes à de nouveaux composants d''interface","Déboguer les problèmes d''interface utilisateur en identifiant et en corrigeant les violations avec des extraits de code suggérés"],"de":["Überprüfen des Benutzeroberflächen-Codes auf Verstöße gegen vordefinierte Einschränkungen","Anwenden konsistenter Tailwind CSS-Standardwerte auf neue Benutzeroberflächenkomponenten","Fehler bei der Benutzeroberfläche durch Identifizierung und Behebung von Verstößen mit vorgeschlagenen Code-Snippets debuggen"],"pt":["Reviewing UI code for violations against predefined constraints","Applying consistent Tailwind CSS defaults to new interface components","Debugging UI issues by identifying and fixing violations with suggested code snippets"],"ru":["Reviewing UI code for violations against predefined constraints","Applying consistent Tailwind CSS defaults to new interface components","Debugging UI issues by identifying and fixing violations with suggested code snippets"],"ar":["Reviewing UI code for violations against predefined constraints","Applying consistent Tailwind CSS defaults to new interface components","Debugging UI issues by identifying and fixing violations with suggested code snippets"]},"limitations":{"en":["Requires use of Tailwind CSS defaults unless custom values are explicitly required","Limited to enforcing predefined UI baseline constraints"],"zh":["需要使用 Tailwind CSS 默认值，除非显式要求自定义值","仅限于执行预定义的 UI 基线约束"],"ja":["カスタム値が明示的に必要な場合を除き、Tailwind CSS のデフォルト値を使用する必要がある","事前定義された UI ベースラインの制約を適用することのみに限定される"],"ko":["자定义 값이 명시적으로 필요하지 않는 한 Tailwind CSS 기본값을 사용해야 함","미리 정의된 UI 기준선 제약을 적용하는 것만으로 제한됨"],"es":["Requiere el uso de los valores predeterminados de Tailwind CSS a menos que se requieran valores personalizados explícitamente","Limitado a hacer cumplir las restricciones de línea de base de interfaz de usuario predefinidas"],"fr":["Nécessite l''utilisation des valeurs par défaut de Tailwind CSS à moins que des valeurs personnalisées soient explicitement requises","Limité à faire respecter les contraintes de ligne de base d''interface utilisateur prédéfinies"],"de":["Erfordert die Verwendung der Standardwerte von Tailwind CSS, sofern nicht explizit benutzerdefinierte Werte erforderlich sind","Begrenzt auf die Durchsetzung vordefinierter UI-Baseline-Einschränkungen"],"pt":["Requires use of Tailwind CSS defaults unless custom values are explicitly required","Limited to enforcing predefined UI baseline constraints"],"ru":["Requires use of Tailwind CSS defaults unless custom values are explicitly required","Limited to enforcing predefined UI baseline constraints"],"ar":["Requires use of Tailwind CSS defaults unless custom values are explicitly required","Limited to enforcing predefined UI baseline constraints"]},"version":3},"contentHash":"9bb2f868098a9d28ce7d10383039a28169d838cea6299f9df3706ecda7932949","qualityScore":24}');
